(() => {'use strict';
 const $=id=>document.getElementById(id),live=window.BemoLive,params=new URL(location.href).searchParams,slug=params.get('store')||'';
 let lang=params.get('lang')==='en'?'en':'ar',shop=null,products=[],category=params.get('category')||'',page=1,next=false,revision=0,controller;
 const filters=window.BemoCatalogFilters?.create($('catalogFilters'),params);
 const words={FILTER_CURRENCY_REQUIRED:['اختر عملة قبل تحديد السعر أو ترتيبه.','Choose a currency before filtering or sorting prices.'],FILTER_PRICE_INVALID:['أدخل نطاق سعر صحيحًا، وبعدد الكسور المناسب للعملة.','Enter a valid price range with the correct decimal places for the currency.'],skip:['انتقل إلى المحتوى','Skip to content'],shop:['تسوق','Shop'],cart:['السلة','Cart'],account:['حسابي','Account'],stores:['المتاجر','Stores'],title:['صفحة المتجر','Storefront'],unavailable:['المتجر غير متاح','Store unavailable'],retry:['إعادة المحاولة','Retry'],allProducts:['جميع المنتجات','All products'],about:['عن المتجر','About the store'],published:['منتج منشور','Published products'],cod:['الدفع عند الاستلام','Cash on delivery'],help:['المساعدة','Help'],search:['بحث داخل المتجر','Search this store'],previous:['السابق','Previous'],next:['التالي','Next'],loading:['جارٍ التحميل…','Loading…'],error:['تعذّر تحميل البيانات. أعد المحاولة.','Could not load data. Please retry.'],empty:['لم ينشر هذا المتجر منتجات بعد.','This store has not published products yet.'],noMatch:['لا توجد منتجات مطابقة.','No matching products.'],all:['الكل','All'],home:['المنزل','Home'],fashion:['الأزياء','Fashion'],electronics:['الإلكترونيات','Electronics'],beauty:['الجمال','Beauty'],sports:['الرياضة','Sports'],other:['أخرى','Other'],add:['أضف للسلة','Add to cart'],options:['اختر الخيارات','Choose options'],out:['نفد المخزون','Out of stock'],added:['أضيف إلى السلة','Added to cart'],stockError:['الكمية في السلة بلغت المخزون المتاح.','Your cart already contains the available stock.'],delivery:['التوصيل: ','Delivery: '],noDescription:['لم يضف المتجر وصفًا بعد.','This store has not added an introduction yet.']};
 const t=k=>words[k][lang==='ar'?0:1],node=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
 function language(){filters?.translate(lang);document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.querySelectorAll('[data-t]').forEach(n=>n.textContent=t(n.dataset.t));document.querySelectorAll('[data-route]').forEach(n=>n.href=n.dataset.route+'?lang='+lang);$('cartLink').href='market.html?view=cart&lang='+lang;$('query').placeholder=t('search');$('languageButton').textContent=lang==='ar'?'English':'العربية';document.title=(shop?.title||t('title'))+' — BEMO';}
 function url(){const u=new URL(location.href);u.searchParams.set('lang',lang);for(const [k,v] of [['q',$('query').value],['category',category],['page',page>1?String(page):'']])v?u.searchParams.set(k,v):u.searchParams.delete(k);filters?.writeParams(u.searchParams);history.replaceState(null,'',u);}
 function profile(){if(!shop)return;$('storeName').textContent=shop.title;$('storeMark').textContent=[...shop.title].slice(0,2).join('');$('storeSlug').textContent='@'+shop.slug;$('storeHeadline').textContent=shop.headline;$('description').textContent=shop.description||t('noDescription');$('storeLocation').textContent=shop.location_label;$('productCount').textContent=String(shop.product_count);$('storeDelivery').textContent=shop.currency&&shop.delivery_fee_minor!==null?t('delivery')+live.money(shop.delivery_fee_minor,shop.currency,lang):'';
  $('categories').replaceChildren();for(const c of ['',...shop.categories]){const b=node('button',t(c||'all'));b.type='button';b.setAttribute('aria-pressed',String(c===category));b.addEventListener('click',()=>{category=c;page=1;profile();loadProducts();});$('categories').append(b);}}
 function render(){const root=$('products');root.replaceChildren();if(!products.length){root.append(node('p',t($('query').value||category||filters?.active()?'noMatch':'empty'),'workspace-empty'));}const ticket=revision;for(const p of products){const a=node('article',undefined,'live-product'),detail='product.html?'+new URLSearchParams({id:p.id,lang}),photo=node('a'),img=node('img');photo.href=detail;img.alt=p.media[0]?.alt_text||p.title;img.loading='lazy';if(p.media[0]){photo.append(img);live.imageUrl(p.media[0].storage_key,controller.signal).then(u=>{if(ticket===revision)img.src=u;}).catch(()=>{img.hidden=true;});}else photo.className='store-product-no-image';const title=node('h2'),link=node('a',p.title);link.href=detail;title.append(link);const available=p.variants.filter(v=>v.stock_on_hand>0),v=(available.length?available:p.variants).slice().sort((a,b)=>a.price_minor-b.price_minor)[0];const price=node('p',v?live.money(v.price_minor,v.currency,lang):t('out'),'live-price'),add=node('button',t(!available.length?'out':p.variants.length===1?'add':'options'),'primary-button');add.type='button';add.disabled=!available.length;add.addEventListener('click',()=>{if(p.variants.length!==1){location.href=detail;return;}try{live.add(v,p.title);$('productStatus').textContent=t('added');}catch(_){$('productStatus').textContent=t('stockError');}});a.append(photo,title,price,node('p',t('cod'),'live-note'),add);root.append(a);}$('previous').disabled=page===1;$('next').disabled=!next;$('page').textContent=String(page);}
 async function loadProducts(){const ticket=++revision;controller?.abort();controller=new AbortController();const activeController=controller;const timer=setTimeout(()=>activeController.abort(),12000);$('productStatus').textContent=t('loading');$('products').replaceChildren();$('error').hidden=true;$('retry').hidden=true;$('next').disabled=$('previous').disabled=true;try{url();const r=await live.catalog({store:slug,search:$('query').value,category,page,...filters?.read()},controller.signal);if(ticket!==revision)return;products=r.products;next=r.hasNext;render();$('productStatus').textContent='';}catch(e){if(ticket===revision){products=[];$('error').textContent=t(words[e.message]?e.message:'error');$('error').hidden=false;$('retry').hidden=false;$('productStatus').textContent='';}}finally{clearTimeout(timer);}}
 async function load(){const ticket=++revision;controller?.abort();controller=new AbortController();const activeController=controller;const timer=setTimeout(()=>activeController.abort(),12000);$('status').textContent=t('loading');$('error').hidden=$('unavailable').hidden=$('retry').hidden=true;$('storeContent').hidden=true;try{shop=await live.store(slug,controller.signal);if(ticket!==revision)return;if(!shop){$('unavailable').hidden=false;return;}if(!shop.categories.includes(category))category='';$('storeContent').hidden=false;language();profile();await loadProducts();}catch(e){if(ticket===revision){if(e.message==='QUERY_INVALID')$('unavailable').hidden=false;else{$('error').textContent=t('error');$('error').hidden=false;$('retry').hidden=false;}}}finally{clearTimeout(timer);$('status').textContent='';}}
 $('searchForm').addEventListener('submit',e=>{e.preventDefault();page=1;loadProducts();});$('previous').addEventListener('click',()=>{if(page>1){page--;loadProducts();}});$('next').addEventListener('click',()=>{if(next){page++;loadProducts();}});$('retry').addEventListener('click',()=>shop?loadProducts():load());$('languageButton').addEventListener('click',()=>{lang=lang==='ar'?'en':'ar';language();profile();try{url();if(shop)render();}catch(e){$('error').textContent=t(words[e.message]?e.message:'error');$('error').hidden=false;}});$('query').value=params.get('q')||'';const p=Number(params.get('page')||1);page=Number.isInteger(p)&&p>0&&p<=834?p:1;language();load();
})();
